/* examples */
function exIcon(st){return st==="verified"||st==="passed"?ic("ok","s-ok"):st==="failed"?ic("bad","s-bad"):ic("warn","s-warn")}
function openEx(name){closePops();if(location.search)history.replaceState(null,"",location.pathname+location.hash);DEEP=0;location.hash="ex="+name}
function buildExamples(list){
  var X=$("exList"),Gl=$("galL");X.textContent="";Gl.textContent="";
  list.forEach(function(r){
    var b=el("button","mi");b.type="button";b.setAttribute("role","menuitem");b.dataset.ex=r.example;b.appendChild(exIcon(r.status));
    var t=el("span","mt");t.appendChild(document.createTextNode(r.title||r.name||r.example));t.appendChild(el("small",null,safeUrl(r.url)?host(r.url):"Local fixture"));b.appendChild(t);
    if(r.fixes!=null)b.appendChild(el("span","k",plural(+r.fixes,"fix","fixes")));
    b.addEventListener("click",function(){openEx(r.example)});X.appendChild(b);
    var li=el("li"),g=el("button");g.type="button";g.appendChild(exIcon(r.status));g.appendChild(el("span","gt",r.title||r.name||r.example));g.appendChild(el("span","gm",(safeUrl(r.url)?host(r.url):"local fixture")+" · "+plural(+r.fixes||0,"fix","fixes")));if
    g.addEventListener("click",function(){openEx(r.example)});li.appendChild(g);Gl.appendChild(li);
  });
  show("gal",list.length>0);markExamples();
}
function markExamples(){var bs=$("exList").querySelectorAll(".mi");for(var i=0;i<bs.length;i++)bs[i].setAttribute("aria-current",S.d&&S.ex&&bs[i].dataset.ex===S.ex?"true":"false")}
var ORDER=["dbt","dagster","entire","accuknox","mkdocs","fixture"];
fetch("examples/index.json").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(j){
  var runs=(j&&Array.isArray(j.runs)?j.runs:[]).filter(function(r){return r&&/^[a-z0-9_-]+$/.test(r.example||"")});
  runs.sort(function(a,b){var x=ORDER.indexOf(a.example),y=ORDER.indexOf(b.example);return (x<0?99:x)-(y<0?99:y)});buildExamples(runs);
}).catch(function(){buildExamples([{example:"dbt",title:"dbt Core with DuckDB",status:"verified"},{example:"dagster",title:"Dagster quickstart",status:"verified"},{example:"fixture",title:"Known-broken test fixture",status:"verified"}])});

