/* live numbers and chips. Only proven results and docs that work appear here. */
function set(id,v){var e=$(id);if(e)e.textContent=v}
function chip(cls,href,icon,title,meta){
 var a=document.createElement("a");a.className="rc card "+cls;a.href=href;
 a.innerHTML='<svg class="ic" aria-hidden="true"><use href="#'+icon+'"/></svg>';
 var b=document.createElement("b"),s=document.createElement("span");b.textContent=title;s.textContent=meta;a.appendChild(b);a.appendChild(s);return a;
}
fetch("runs/index.json").then(function(r){return r.json()}).then(function(j){
 var best={},rank=function(r){return r.status==="verified"&&(+r.fixes||0)>0?2:(r.status==="passed"||r.status==="verified")?1:0};
 (j.runs||[]).forEach(function(r){if(r.fixture||!r.url)return;var b=best[r.url];if(!b||rank(r)>rank(b))best[r.url]=r});
 var pages=Object.keys(best).map(function(k){return best[k]}),fx=pages.filter(function(r){return rank(r)===2}),ok=pages.filter(function(r){return rank(r)===1});
 if(!fx.length&&!ok.length)return;
 set("n-fix",fx.length);set("s-fix",fx.length);set("n-ok",ok.length);set("s-ok",ok.length);
 var box=$("replays");box.textContent="";
 function nm(r){var t=r.title||r.target;return t.length<14&&r.target?t+", "+r.target:t}
 fx.sort(function(a,b){return (b.fixes||0)-(a.fixes||0)}).slice(0,8).forEach(function(r){
  box.appendChild(chip("g","doc-test/#ex="+encodeURIComponent(r.id),"i-check",nm(r),r.fixes+(r.fixes===1?" fix proven":" fixes proven")))});
 ok.slice(0,4).forEach(function(r){
  box.appendChild(chip("bl","doc-test/#ex="+encodeURIComponent(r.id),"i-check",nm(r),"docs work"))});
}).catch(function(){});
fetch("audits/index.json").then(function(r){return r.json()}).then(function(j){
 var a=j.audits||[];if(!a.length)return;
 var st=a.reduce(function(n,x){return n+(+x.stale||0)},0);
 set("n-rep",a.length);set("s-rep",a.length);set("n-stale",st);set("s-stale",st);
 var box=$("audits");box.textContent="";
 a.forEach(function(x){
  var m=x.stale?x.stale+" stale of "+x.pages:x.uncovered?x.uncovered+" features to document":x.pages+" pages checked";
  box.appendChild(chip("v","doc-audit/?id="+encodeURIComponent(x.id),"i-list",x.repo,m))});
}).catch(function(){});

