"""Give the FirstRun homepage life: full-bleed film, open numbers, PR shelf, ledgers, plan track,
open compare, race-track build log, soft depth and fluid reveal. Nav and section flow stay."""
import re, sys
p = sys.argv[1]
track_js = open(sys.argv[2], encoding="utf-8").read()
s = open(p, encoding="utf-8").read()


def rep(old, new, n=1):
    global s
    assert s.count(old) == n, (s.count(old), old[:100])
    s = s.replace(old, new)


def between(a, b):
    i = s.index(a); j = s.index(b, i) + len(b)
    return i, j


def ic(name, extra=""):
    return f'<svg class="ic"{extra} aria-hidden="true"><use href="#{name}"/></svg>'


# ---------------------------------------------------------------- head: js flag for reveal
rep('<meta name="color-scheme" content="light">',
    '<meta name="color-scheme" content="light">\n<script>document.documentElement.className="js"</script>')

# ---------------------------------------------------------------- tokens: depth, ease, air
rep('--sh:0 1px 2px oklch(30% .02 255/.06);',
    '--sh:0 1px 2px oklch(30% .02 255/.06);\n'
    '--lift:0 1px 2px oklch(30% .03 256/.05),0 8px 24px -10px oklch(35% .06 256/.16),0 24px 56px -28px oklch(35% .06 256/.18);\n'
    '--lift-h:0 2px 4px oklch(30% .03 256/.06),0 16px 36px -12px oklch(35% .07 256/.22),0 36px 72px -30px oklch(35% .07 256/.24);\n'
    '--ease:cubic-bezier(.16,1,.3,1);--road:oklch(22% .012 255/.08);')
rep('--pad:clamp(44px,6vw,72px)}', '--pad:clamp(64px,9vw,120px)}')
rep('.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;box-shadow:var(--sh)}',
    '.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:var(--lift)}\n'
    '/* motion: one fade and rise as a block enters, staggered inside a group */\n'
    'html.js .rv{opacity:0;transform:translateY(22px);transition:opacity .9s var(--ease),transform .9s var(--ease)}\n'
    'html.js .rv.in{opacity:1;transform:none}\n'
    '.app,.tool,.pr,.shots figure,.anno figure{transition:transform .6s var(--ease),box-shadow .6s var(--ease),border-color .2s}\n'
    '.app:hover,.tool:hover,.pr:hover,.shots figure:hover{transform:translateY(-4px);box-shadow:var(--lift-h)}')

# ---------------------------------------------------------------- hero: a soft glow behind the hero only
rep('#hero{text-align:center;padding-top:clamp(20px,4vw,44px)}',
    '#hero{text-align:center;padding-top:clamp(28px,5vw,64px);position:relative;isolation:isolate}\n'
    '#hero:before{content:"";position:absolute;z-index:-1;left:50%;top:-140px;width:min(1400px,140vw);height:760px;transform:translateX(-50%);pointer-events:none;'
    'background:radial-gradient(34% 42% at 28% 34%,oklch(84% .09 256/.42),transparent 72%),radial-gradient(30% 38% at 74% 28%,oklch(84% .1 295/.34),transparent 72%),'
    'radial-gradient(28% 34% at 52% 78%,oklch(90% .08 150/.30),transparent 72%)}\n'
    '#hero>*{animation:rise 1s var(--ease) both}#hero>:nth-child(2){animation-delay:.06s}#hero>:nth-child(3){animation-delay:.12s}#hero>:nth-child(4){animation-delay:.18s}#hero>:nth-child(n+5){animation-delay:.24s}\n'
    '@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}')
rep('.box{display:flex;gap:8px;align-items:center;margin:24px auto 0;max-width:620px;border-radius:14px;padding:6px 6px 6px 18px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--sh)}',
    '.box{display:flex;gap:8px;align-items:center;margin:28px auto 0;max-width:640px;border-radius:16px;padding:7px 7px 7px 20px;background:var(--panel);border:1px solid var(--line);box-shadow:var(--lift)}')
rep('.apps{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:22px;text-align:left}',
    '.apps{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:40px;text-align:left}')

# ---------------------------------------------------------------- film: full bleed, edges fade into the page
i, j = between('<figure class="film card" id="film">', '</figure>\n')
s = s[:i] + s[j:]
film = ('<section id="film" class="film" aria-label="Launch film">\n<div class="reel rv">\n'
        '<video id="reel" muted loop playsinline preload="metadata" poster="assets/launch-poster.jpg" aria-label="FirstRun launch film, 44 seconds, plays silently on a loop">'
        '<source src="assets/firstrun-launch.mp4" type="video/mp4"></video>\n'
