js = r'''
/* reveal: each block fades and rises once as it enters, staggered inside its group */
(function(){
 var rm=matchMedia("(prefers-reduced-motion:reduce)").matches;
 var groups=[".apps>.app","#steps .row",".shots>figure",".anno ol>li",".tools>.tool",".shelf>.pr",".tl>li","#about .about"];
 groups.forEach(function(q){Array.prototype.forEach.call(document.querySelectorAll(q),function(el,i){el.classList.add("rv");el.style.transitionDelay=Math.min(i,5)*80+"ms"})});
 var els=document.querySelectorAll(".rv");
 if(rm||!("IntersectionObserver" in window)){Array.prototype.forEach.call(els,function(e){e.classList.add("in")});return}
 var io=new IntersectionObserver(function(en){en.forEach(function(e){if(e.isIntersecting){e.target.classList.add("in");io.unobserve(e.target);
  e.target.addEventListener("transitionend",function(){e.target.style.transitionDelay=""},{once:true})}})},{rootMargin:"0px 0px -8% 0px",threshold:.05});
 Array.prototype.forEach.call(els,function(e){io.observe(e)});
})();

/* the big numbers count up once when the row enters */
(function(){
 var row=document.querySelector(".figs");if(!row)return;
 if(matchMedia("(prefers-reduced-motion:reduce)").matches||!("IntersectionObserver" in window))return;
 function run(){Array.prototype.forEach.call(row.querySelectorAll("b.cu"),function(b){
  var t=b.textContent.trim(),m=/^(\$?)(\d+(?:\.\d+)?)$/.exec(t);if(!m)return;
  var pre=m[1],to=parseFloat(m[2]),dp=(m[2].split(".")[1]||"").length,t0=null,T=1100;
  (function f(now){if(t0===null)t0=now;var k=Math.min(1,(now-t0)/T),v=to*(1-Math.pow(1-k,4));b.textContent=pre+v.toFixed(dp);if(k<1)requestAnimationFrame(f);else b.textContent=t})(performance.now());
 })}
 var io=new IntersectionObserver(function(en){if(en[0].isIntersecting){io.disconnect();setTimeout(run,150)}},{threshold:.4});io.observe(row);
})();

/* launch film: silent loop, plays only while on screen */
(function(){
 var v=$("reel"),pp=$("pp"),mu=$("mu");if(!v)return;
 var held=matchMedia("(prefers-reduced-motion:reduce)").matches;
 function sync(){pp.textContent=v.paused?"Play":"Pause"}
 function play(){var p=v.play();if(p&&p.catch)p.catch(function(){})}
 pp.addEventListener("click",function(){if(v.paused){held=false;play()}else{held=true;v.pause()}});
 mu.addEventListener("click",function(){v.muted=!v.muted;mu.textContent=v.muted?"Sound on":"Sound off";if(!v.muted&&v.paused){held=false;play()}});
 v.addEventListener("play",sync);v.addEventListener("pause",sync);sync();
 if("IntersectionObserver" in window){new IntersectionObserver(function(en){if(en[0].isIntersecting){if(!held)play()}else v.pause()},{threshold:.35}).observe(v)}
 else if(!held)play();
})();

/* PR shelf: arrows step one card */
(function(){
 var sh=$("shelf"),pv=$("prP"),nx=$("prN");if(!sh)return;
 function w(){var c=sh.querySelector(".pr");return c?c.getBoundingClientRect().width+20:400}
 function upd(){pv.disabled=sh.scrollLeft<8;nx.disabled=sh.scrollLeft+sh.clientWidth>=sh.scrollWidth-8}
 var sm=matchMedia("(prefers-reduced-motion:reduce)").matches?"auto":"smooth";
 pv.addEventListener("click",function(){sh.scrollBy({left:-w(),behavior:sm})});
 nx.addEventListener("click",function(){sh.scrollBy({left:w(),behavior:sm})});
 sh.addEventListener("keydown",function(e){if(e.key==="ArrowRight"){e.preventDefault();sh.scrollBy({left:w(),behavior:sm})}if(e.key==="ArrowLeft"){e.preventDefault();sh.scrollBy({left:-w(),behavior:sm})}});
 sh.addEventListener("scroll",upd,{passive:true});addEventListener("resize",upd);upd();
})();

/* race track: a road through the build log, driven once when it enters */
